[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<meta name="description" content="Engineering insights, product updates, and community stories from DeployCloud.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ── Design Tokens ── */
:root {
  --color-accent: oklch(55% 0.22 260);
  --color-accent-hover: oklch(50% 0.22 260);
  --color-accent-subtle: oklch(96% 0.03 260);
  --color-text: oklch(14% 0.01 260);
  --color-text-secondary: oklch(40% 0.02 260);
  --color-text-tertiary: oklch(55% 0.02 260);
  --color-border: oklch(90% 0.005 260);
  --color-border-hover: oklch(80% 0.01 260);
  --color-bg: oklch(99% 0.002 260);
  --color-surface: #ffffff;
  --color-surface-hover: oklch(97% 0.005 260);
  --color-fg-inverse: #ffffff;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.04);
  --shadow-md: 0 1px 4px rgba(0,0,0,.06), 0 4px 16px rgba(0,0,0,.04);
  --shadow-lg: 0 1px 4px rgba(0,0,0,.08), 0 8px 32px rgba(0,0,0,.06);
  --shadow-xl: 0 1px 4px rgba(0,0,0,.10), 0 16px 48px rgba(0,0,0,.08);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --max-width: 1280px;
  --header-height: 64px;
}

/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  min-height: 100vh;
}
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input { font: inherit; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Header ── */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
}
.header-inner {
  display: flex;
  align-items: center;
  height: var(--header-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  gap: 32px;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -.02em;
  color: var(--color-text);
  flex-shrink: 0;
}
.header-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 18px;
  font-weight: 800;
}
.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.header-nav > li { position: relative; }
.header-nav > li > button {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  transition: color .15s, background .15s;
  white-space: nowrap;
}
.header-nav > li > button:hover,
.header-nav > li > button.active {
  color: var(--color-text);
  background: var(--color-surface-hover);
}
.header-nav > li > button svg { width: 14px; height: 14px; opacity: .5; transition: transform .2s; }
.header-nav > li > button.active svg { transform: rotate(180deg); }
.header-nav-link {
  display: flex;
  align-items: center;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  transition: color .15s, background .15s;
}
.header-nav-link:hover { color: var(--color-text); background: var(--color-surface-hover); }
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  flex-shrink: 0;
}
.header-actions .btn-ghost {
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-md);
  transition: color .15s, background .15s;
}
.header-actions .btn-ghost:hover { color: var(--color-text); background: var(--color-surface-hover); }
.header-actions .btn-primary-sm {
  padding: 8px 18px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  transition: background .15s;
}
.header-actions .btn-primary-sm:hover { background: var(--color-accent-hover); }

/* ── Mega Menu ── */
.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 32px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .2s, visibility .2s, transform .2s;
  z-index: 200;
}
.mega-menu.open { opacity: 1; visibility: visible; pointer-events: auto; }
.mega-menu-wide { width: 720px; display: flex; gap: 48px; }
.mega-menu-col { flex: 1; }
.mega-menu-col h4 {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--color-text-tertiary);
  margin-bottom: 12px;
  padding: 0 4px;
}
.mega-menu-item {
  display: flex;
  flex-direction: column;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  transition: background .12s;
  gap: 2px;
}
.mega-menu-item:hover { background: var(--color-surface-hover); }
.mega-menu-item .label { font-size: 14px; font-weight: 500; color: var(--color-text); }
.mega-menu-item .desc { font-size: 12px; color: var(--color-text-tertiary); line-height: 1.4; }
.mega-menu-medium { width: 580px; display: flex; gap: 48px; }

/* ── Page Hero ── */
.page-hero {
  padding: 64px 0 48px;
  text-align: center;
}
.page-hero h1 {
  font-size: 48px;
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
  margin-bottom: 16px;
  color: var(--color-text);
}
.page-hero p {
  font-size: 18px;
  color: var(--color-text-secondary);
  max-width: 560px;
  margin: 0 auto;
  line-height: 1.6;
}

/* ── Category Filters ── */
.filters-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 0 40px;
  flex-wrap: wrap;
}
.filters-pills {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
  min-width: 0;
}
.filter-pill {
  padding: 7px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 100px;
  transition: all .15s;
  white-space: nowrap;
  cursor: pointer;
}
.filter-pill:hover {
  border-color: var(--color-border-hover);
  color: var(--color-text);
  background: var(--color-surface);
}
.filter-pill.active {
  background: var(--color-text);
  border-color: var(--color-text);
  color: #fff;
}
.search-wrap {
  position: relative;
  width: 260px;
  flex-shrink: 0;
}
.search-wrap svg {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--color-text-tertiary);
  pointer-events: none;
}
.search-input {
  width: 100%;
  padding: 9px 14px 9px 40px;
  font-size: 14px;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 100px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.search-input::placeholder { color: var(--color-text-tertiary); }
.search-input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0,114,245,.1);
}

/* ── Featured Articles ── */
.featured-section {
  padding: 0 0 64px;
}
.featured-section h2 {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--color-text-tertiary);
  margin-bottom: 20px;
}
.featured-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.featured-card {
  position: relative;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  transition: border-color .2s, box-shadow .2s, transform .2s;
  cursor: pointer;
  overflow: hidden;
}
.featured-card:hover {
  border-color: var(--color-border-hover);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.featured-card:first-child {
  grid-column: span 2;
  flex-direction: row;
  gap: 40px;
  padding: 0;
  overflow: hidden;
  align-items: stretch;
}
.featured-card:first-child .fc-content {
  flex: 1;
  padding: 36px 0 36px 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.featured-card:first-child .fc-stats {
  flex: 1;
  background: var(--color-text);
  color: #fff;
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 20px;
}
.fc-tag {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-accent);
  background: var(--color-accent-subtle);
  border-radius: 100px;
  width: fit-content;
  margin-bottom: 16px;
}
.featured-card:first-child .fc-tag { margin-bottom: 12px; }
.fc-date {
  font-size: 13px;
  color: var(--color-text-tertiary);
  margin-bottom: 8px;
}
.fc-title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -.02em;
  margin-bottom: 10px;
  color: var(--color-text);
}
.featured-card:first-child .fc-title { font-size: 28px; }
.fc-excerpt {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.featured-card:first-child .fc-excerpt { -webkit-line-clamp: 4; }
.fc-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
}
.fc-author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: oklch(85% 0.03 260);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: var(--color-text-secondary);
}
.fc-author-name { font-size: 13px; font-weight: 500; color: var(--color-text); }
.fc-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.fc-stat-value {
  font-size: 36px;
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1;
}
.fc-stat-label {
  font-size: 13px;
  color: oklch(70% 0.02 260);
  line-height: 1.4;
}
.fc-stats-extra {
  font-size: 12px;
  color: oklch(60% 0.02 260);
  line-height: 1.5;
  margin-top: 8px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,.1);
}

/* ── Latest News ── */
.latest-section {
  padding: 0 0 64px;
  border-top: 1px solid var(--color-border);
  padding-top: 56px;
}
.latest-section h2 {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -.02em;
  margin-bottom: 24px;
}
.post-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.post-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: border-color .2s, box-shadow .2s, transform .2s;
  cursor: pointer;
}
.post-card:hover {
  border-color: var(--color-border-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.post-card.hidden { display: none; }
.post-tag {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--color-accent);
  background: var(--color-accent-subtle);
  border-radius: 100px;
  width: fit-content;
  margin-bottom: 12px;
}
.post-date {
  font-size: 13px;
  color: var(--color-text-tertiary);
  margin-bottom: 6px;
}
.post-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -.01em;
  margin-bottom: 8px;
}
.post-excerpt {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.55;
  flex: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 16px;
}
.post-author {
  display: flex;
  align-items: center;
  gap: 8px;
}
.post-author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: oklch(85% 0.03 260);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--color-text-secondary);
  flex-shrink: 0;
}
.post-author-name { font-size: 13px; font-weight: 500; color: var(--color-text-secondary); }

/* ── No Results ── */
.no-results {
  display: none;
  text-align: center;
  padding: 64px 24px;
  grid-column: 1 / -1;
}
.no-results.visible { display: block; }
.no-results-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: var(--color-accent-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
}
.no-results-icon svg { width: 24px; height: 24px; color: var(--color-accent); }
.no-results h3 { font-size: 18px; font-weight: 600; margin-bottom: 8px; }
.no-results p { font-size: 14px; color: var(--color-text-secondary); max-width: 400px; margin: 0 auto; }

/* ── Show More ── */
.show-more-wrap {
  text-align: center;
  padding: 16px 0 0;
}
.btn-show-more {
  padding: 10px 28px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 100px;
  transition: all .15s;
}
.btn-show-more:hover {
  border-color: var(--color-text);
  background: var(--color-surface-hover);
}
.btn-show-more:disabled {
  opacity: .4;
  cursor: not-allowed;
}

/* ── CTA Banner ── */
.cta-section {
  padding: 32px 0 64px;
}
.cta-banner {
  background: var(--color-text);
  border-radius: var(--radius-xl);
  padding: 56px 64px;
  display: flex;
  align-items: center;
  gap: 48px;
  overflow: hidden;
  position: relative;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, oklch(55% 0.22 260 / .15), transparent 70%);
  pointer-events: none;
}
.cta-content { flex: 1; position: relative; z-index: 1; }
.cta-content h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
  color: #fff;
  margin-bottom: 16px;
}
.cta-content p {
  font-size: 16px;
  color: oklch(70% 0.02 260);
  line-height: 1.6;
  margin-bottom: 24px;
}
.cta-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.btn-primary {
  padding: 12px 28px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
  background: #fff;
  border-radius: 100px;
  transition: transform .15s, box-shadow .15s;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.btn-primary:hover { transform: translateY(-1px); box-shadow: 0 4px 16px rgba(255,255,255,.2); }
.btn-secondary-outline {
  padding: 12px 28px;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  background: transparent;
  border: 1px solid rgba(255,255,255,.3);
  border-radius: 100px;
  transition: all .15s;
}
.btn-secondary-outline:hover { border-color: #fff; background: rgba(255,255,255,.08); }
.cta-enterprise {
  flex: 0 0 280px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  padding: 28px;
  position: relative;
  z-index: 1;
}
.cta-enterprise h4 {
  font-size: 16px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 8px;
}
.cta-enterprise p {
  font-size: 13px;
  color: oklch(70% 0.02 260);
  line-height: 1.5;
  margin-bottom: 16px;
}
.btn-enterprise {
  padding: 10px 22px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: rgba(255,255,255,.1);
  border-radius: 100px;
  transition: background .15s;
}
.btn-enterprise:hover { background: rgba(255,255,255,.18); }

/* ── Footer ── */
.footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 64px 0 48px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 14px;
  color: var(--color-text);
}
.footer-col ul { display: flex; flex-direction: column; gap: 8px; }
.footer-col a {
  font-size: 13px;
  color: var(--color-text-tertiary);
  transition: color .15s;
}
.footer-col a:hover { color: var(--color-text); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--color-border);
  gap: 16px;
  flex-wrap: wrap;
}
.footer-bottom .footer-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  font-size: 14px;
}
.footer-bottom .footer-logo-icon {
  width: 24px;
  height: 24px;
  background: var(--color-text);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  font-weight: 800;
}
.footer-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--color-text-tertiary);
}
.footer-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: oklch(65% 0.19 145);
  flex-shrink: 0;
}

/* ── Responsive ── */
@media (max-width: 1100px) {
  .featured-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-card:first-child { grid-column: span 2; }
  .featured-card:first-child .fc-title { font-size: 24px; }
  .post-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .cta-banner { flex-direction: column; padding: 40px; gap: 32px; }
  .cta-enterprise { flex: 0 0 auto; width: 100%; }
}
@media (max-width: 768px) {
  .header-nav { display: none; }
  .header-actions .btn-ghost { display: none; }
  .page-hero h1 { font-size: 32px; }
  .featured-grid { grid-template-columns: 1fr; }
  .featured-card:first-child { grid-column: span 1; flex-direction: column; }
  .featured-card:first-child .fc-content { padding: 28px 28px 0; }
  .featured-card:first-child .fc-stats { padding: 24px 28px 28px; }
  .featured-card:first-child .fc-title { font-size: 22px; }
  .post-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .filters-bar { flex-direction: column; align-items: stretch; }
  .search-wrap { width: 100%; }
