/* ── Category Filtering + Search ── */
(function() {
  const pills = document.querySelectorAll('.filter-pill');
  const searchInput = document.getElementById('search-input');
  const postGrid = document.getElementById('post-grid');
  const noResults = document.getElementById('no-results');
  const showMoreBtn = document.getElementById('btn-show-more');
  let activeCategory = 'all';
  let searchQuery = '';

  function getVisibleCards() {
    return postGrid.querySelectorAll('.post-card:not(.hidden)');
  }

  function applyFilters() {
    const cards = postGrid.querySelectorAll('.post-card');
    const initiallyVisible = 8;
    let visibleCount = 0;
    let totalVisible = 0;

    cards.forEach((card, i) => {
      const cat = card.dataset.category;
      const keywords = (card.dataset.keywords || '').toLowerCase();
      const text = (card.querySelector('.post-title')?.textContent + ' ' +
                    card.querySelector('.post-excerpt')?.textContent + ' ' +
                    keywords).toLowerCase();

      const catMatch = activeCategory === 'all' || cat === activeCategory;
      const searchMatch = !searchQuery || text.includes(searchQuery.toLowerCase());
      const shouldShow = catMatch && searchMatch;

      // Hide cards beyond index 7 (keep initial 8 visible), unless already revealed by show-more
      const isRevealed = !card.classList.contains('hidden-beyond-initial');

      if (shouldShow) {
        totalVisible++;
        if (isRevealed) {
          card.classList.remove('hidden');
          visibleCount++;
        } else {
          card.classList.add('hidden');
        }
      } else {
        card.classList.add('hidden');
      }
    });

    // Update no-results state
    if (totalVisible === 0) {
      noResults.classList.add('visible');
      showMoreBtn.disabled = true;
    } else {
      noResults.classList.remove('visible');
      showMoreBtn.disabled = totalVisible <= visibleCount;
    }

    // Hide show more if no hidden matching cards remain
    const hiddenMatching = postGrid.querySelectorAll('.post-card.hidden:not(.no-results)').length;
    const allHiddenAreNonMatching = Array.from(postGrid.querySelectorAll('.post-card.hidden')).every(
      c => c.dataset.category !== activeCategory && activeCategory !== 'all'
    );
  }

  pills.forEach(pill => {
    pill.addEventListener('click', function() {
      pills.forEach(p => p.classList.remove('active'));
      this.classList.add('active');
      activeCategory = this.dataset.category;

      // Reset show-more state
      const allCards = postGrid.querySelectorAll('.post-card');
      allCards.forEach((card, i) => {
        if (i >= 8) {
          card.classList.add('hidden');
        }
      });

      applyFilters();
    });
  });

  searchInput.addEventListener('input', function() {
    searchQuery = this.value.trim();

    // Reset show-more state
    const allCards = postGrid.querySelectorAll('.post-card');
    allCards.forEach((card, i) => {
      if (i >= 8) {
        card.classList.add('hidden');
      }
    });

    applyFilters();
  });
})();

/* ── Show More Posts ── */
(function() {
  const btn = document.getElementById('btn-show-more');
  const grid = document.getElementById('post-grid');
  let revealIndex = 8;
  const batchSize = 3;

  btn.addEventListener('click', function() {
    const hiddenCards = grid.querySelectorAll('.post-card.hidden');
    if (hiddenCards.length === 0) {
      btn.disabled = true;
      return;
    }

    let revealed = 0;
    for (const card of hiddenCards) {
      if (revealed >= batchSize) break;
      // Only reveal cards that match current filters
      const activePill = document.querySelector('.filter-pill.active');
      const activeCategory = activePill ? activePill.dataset.category : 'all';
      const cat = card.dataset.category;
      const catMatch = activeCategory === 'all' || cat === activeCategory;

      if (catMatch) {
        card.classList.remove('hidden');
        revealed++;
      }
    }

    // Check if more remain
    const remaining = grid.querySelectorAll('.post-card.hidden');
    if (remaining.length === 0 || revealed === 0) {
      btn.disabled = true;
    }
  });
})();

